#pragma once
#include "PatternTools.h"
static void testNoteConditions(const File& root,Assets& assets){
    bool cycleCorrect=true;for(int every=1;every<=16;++every)for(int step=1;step<=every;++step)for(uint64_t pass=0;pass<64;++pass)cycleCorrect&=noteConditionMatches(every,step,pass)==(pass%(uint64_t)every==(uint64_t)step-1);expect(cycleCorrect,"all 1-16 note condition cycles choose exactly the requested repeat");
    auto p=emptyProject();p.songMode=false;p.loop=true;p.bpm=300;p.patterns[0].length=1;p.clips.clear();p.tracks[7].send=0;p.tracks[7].release=.02f;p.patterns[0].lanes[7]={{0,.1,60,.8f,1,1,4,4}};
    auto audio=render(p,assets,root,48000,127);bool gated=true;for(int pass=0;pass<5;++pass)gated&=(audio.getMagnitude(0,pass*9600,4000)>.001f)==(pass==3);expect(gated,"PAT condition sounds only on the fourth loop and stays silent on rejected passes");expect(audio==render(p,assets,root,48000,1024),"conditional loop audio is independent of callback size");
    auto engine=makeEngine(p,assets,root);AudioBuffer<float> block(2,40000);engine->render(block.getWritePointer(0),block.getWritePointer(1),35000);engine->stop();engine->render(block.getWritePointer(0),block.getWritePointer(1),1);engine->start();engine->render(block.getWritePointer(0),block.getWritePointer(1),4000);expect(block.getMagnitude(0,0,4000)==0&&engine->completedLoops.load()==0,"Stop and Play reset conditional PAT counting to the first pass");
    engine=makeEngine(p,assets,root);engine->render(block.getWritePointer(0),block.getWritePointer(1),30000);engine->seekRequested.store(.01);engine->render(block.getWritePointer(0),block.getWritePointer(1),2000);expect(block.getMagnitude(0,0,2000)==0&&engine->chasedNotes.load()==0,"PAT seek resets the cycle and does not chase a rejected gate");
    auto song=p;song.songMode=true;song.loop=false;song.clips={{7,0,0,4},{7,0,4,4}};auto reference=song;reference.patterns[0].lanes[7][0].conditionEvery=1;reference.patterns[0].lanes[7][0].conditionStep=1;reference.clips={{7,0,3,1},{7,0,7,1}};expect(render(song,assets,root,80000,733)==render(reference,assets,root,80000,97),"Song conditions continue across separate clips and match an explicitly arranged fourth/eighth repeat");
    auto compiled=std::make_unique<Playback>();String warnings;expect(compilePlayback(song,assets,root,*compiled,warnings).wasOk()&&compiled->eventCount==8&&compiled->events[4].conditionPass==4,"compiled condition phase follows Song time rather than restarting per clip");
    auto ratchets=song;ratchets.patterns[0].lanes[7][0].ratchets=4;expect(compilePlayback(ratchets,assets,root,*compiled,warnings).wasOk()&&compiled->eventCount==32&&compiled->events[12].conditionPass==3&&compiled->events[15].conditionPass==3,"every ratchet sub-gate shares its parent note repeat condition");ratchets.patterns[0].lanes[7][0].probability=0;expect(render(ratchets,assets,root,80000).getMagnitude(0,0,80000)==0,"zero Chance still rejects an otherwise accepted conditional ratchet");
    auto held=song;held.patterns[0].lanes[7][0].length=.8;for(int pass=2;pass<=3;++pass){engine=makeEngine(held,assets,root);engine->seekRequested.store(pass+.2);engine->render(block.getWritePointer(0),block.getWritePointer(1),2000);expect((engine->chasedNotes.load()==1)==(pass==3)&&(block.getMagnitude(0,0,2000)>.001f)==(pass==3),"Song seek uses the same repeat condition for held-note chase as note onset");}
    held.loop=true;held.markers={{"conditional-section","Conditional section",3.2,3.5,0}};held.loopSection="conditional-section";engine=makeEngine(held,assets,root);engine->render(block.getWritePointer(0),block.getWritePointer(1),20000);expect(engine->completedLoops.load()>4&&engine->chasedNotes.load()>4&&block.getMagnitude(0,15000,4000)>.001f,"section looping preserves accepted Song timeline gates across repeated wraps");
    auto stored=root.getChildFile("conditional-notes.pulse");Project loaded;expect(saveProject(song,stored).wasOk()&&loadProject(stored,loaded).wasOk()&&loaded.patterns[0].lanes[7]==song.patterns[0].lanes[7],"schema 21 checked save/reopen preserves repeat conditions");
    auto before=JSON::toString(projectToJson(loaded));for(int invalid=0;invalid<7;++invalid){auto data=projectToJson(song);auto* note=data["patterns"][0]["lanes"][7][0].getDynamicObject();switch(invalid){case 0:note->removeProperty("conditionEvery");break;case 1:note->setProperty("conditionStep",5);break;case 2:note->setProperty("conditionEvery",0);break;case 3:note->setProperty("conditionStep",true);break;case 4:note->setProperty("conditionEvery",4.5);break;case 5:note->setProperty("conditionStep","4");break;case 6:data.getDynamicObject()->setProperty("schema",20);break;}expect(projectFromJson(data,loaded).failed()&&JSON::toString(projectToJson(loaded))==before,"malformed/missing or mislabeled conditional notes reject atomically");}
    auto legacy=song;legacy.patterns[0].lanes[7][0].conditionEvery=legacy.patterns[0].lanes[7][0].conditionStep=1;for(int schema=1;schema<=20;++schema){auto old=projectToJson(legacy);old.getDynamicObject()->setProperty("schema",schema);for(auto& pat:*old["patterns"].getArray())for(auto& lane:*pat["lanes"].getArray())for(auto& note:*lane.getArray()){note.getDynamicObject()->removeProperty("conditionEvery");note.getDynamicObject()->removeProperty("conditionStep");}expect(projectFromJson(old,loaded).wasOk()&&loaded.patterns[0].lanes[7][0].conditionEvery==1&&loaded.patterns[0].lanes[7][0].conditionStep==1,"all earlier schemas load unconditional notes without changing their articulation");}
    auto bad=song;bad.patterns[0].lanes[7][0].conditionStep=17;expect(compilePlayback(bad,assets,root,*compiled,warnings).failed(),"invalid in-memory repeat data cannot reach the audio callback");auto saved=stored.loadFileAsString();expect(saveProject(bad,stored).failed()&&stored.loadFileAsString()==saved,"invalid repeat data cannot overwrite a valid project");
    NoteToolOptions options;options.positionStrength=0;std::vector<Note> notes;auto lane=song.patterns[0].lanes[7];expect(processNotes(lane,1,{},options,notes).wasOk()&&notes==lane,"ordinary note tools preserve repeat metadata");double length=0;expect(pasteLaneNotes(lane,{},1,NotePasteMode::atStart,0,false,notes,length).wasOk()&&notes==lane,"cross-pattern note clipboard preserves repeat metadata");
    Project edited;auto operations=JSON::parse(R"([{"op":"set_notes","pattern":0,"track":7,"notes":[{"beat":0,"length":0.1,"pitch":60,"velocity":0.8,"conditionEvery":16,"conditionStep":16}]}])");expect(applyControlEdits(song,operations,edited).wasOk()&&edited.patterns[0].lanes[7][0].conditionStep==16,"MCP authors the maximum sixteen-repeat condition");auto untouched=JSON::toString(projectToJson(edited));for(auto badNote:{R"({"conditionEvery":2,"conditionStep":3})",R"({"conditionStep":2})",R"({"conditionEvery":0})",R"({"conditionEvery":true})",R"({"conditionEvery":2.5})"}){auto edits=JSON::parse(R"([{"op":"set_song","title":"Must not commit"},{"op":"set_notes","pattern":0,"track":7,"notes":[{"beat":0,"length":0.1,"pitch":60,"velocity":0.8}]}])");auto fields=JSON::parse(badNote);for(auto& property:fields.getDynamicObject()->getProperties())edits[1]["notes"][0].getDynamicObject()->setProperty(property.name,property.value);expect(applyControlEdits(song,edits,edited).failed()&&JSON::toString(projectToJson(edited))==untouched,"invalid MCP condition rejects the entire multi-operation batch");}
    auto midiFile=root.getChildFile("conditional-notes.mid");expect(writeMidi(song,midiFile).wasOk(),"Song MIDI export bakes conditional timeline choices");MidiFile midi;auto input=midiFile.createInputStream();bool read=input&&midi.readFrom(*input);std::vector<double> onsets;if(read)for(int i=0;i<midi.getNumTracks();++i)for(int e=0;e<midi.getTrack(i)->getNumEvents();++e){const auto& message=midi.getTrack(i)->getEventPointer(e)->message;if(message.isNoteOn())onsets.push_back(message.getTimeStamp()/midi.getTimeFormat());}expect(onsets==std::vector<double>({3,7}),"MIDI output includes only accepted third/seventh-beat notes");
    expect(writeMidi(p,midiFile).wasOk(),"PAT MIDI export evaluates its first pass");input=midiFile.createInputStream();read=input&&midi.readFrom(*input);int count=0;if(read)for(int i=0;i<midi.getNumTracks();++i)for(int e=0;e<midi.getTrack(i)->getNumEvents();++e)count+=midi.getTrack(i)->getEventPointer(e)->message.isNoteOn();expect(read&&count==0,"a fourth-pass-only PAT note is absent from first-pass MIDI export");
}
